import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const a="/assets/shots/cert.png",u=JSON.parse('{"title":"证书签发","description":"CertHub 的 12 种签发来源、ACME 流程、DNS-01 / HTTP-01 验证方式选择、EAB、云厂商免费证书与证书导出。","frontmatter":{"title":"证书签发","description":"CertHub 的 12 种签发来源、ACME 流程、DNS-01 / HTTP-01 验证方式选择、EAB、云厂商免费证书与证书导出。"},"headers":[],"relativePath":"docs/issue.md","filePath":"docs/issue.md","lastUpdated":null}'),c={name:"docs/issue.md"};function s(i,t,l,n,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="证书签发" tabindex="-1">证书签发 <a class="header-anchor" href="#证书签发" aria-label="Permalink to &quot;证书签发&quot;">​</a></h1><p>CertHub 内置自研 ACME v2 客户端，同时支持云厂商免费证书、商业 CA、本地自签与自有证书导入。</p><h2 id="签发来源" tabindex="-1">签发来源 <a class="header-anchor" href="#签发来源" aria-label="Permalink to &quot;签发来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>类型</th><th>有效期</th><th>验证方式</th><th>说明</th></tr></thead><tbody><tr><td>Let&#39;s Encrypt</td><td>ACME CA</td><td>90 天</td><td>DNS-01 / HTTP-01</td><td>公益 CA，支持泛域名</td></tr><tr><td>Google Trust Services</td><td>ACME CA</td><td>90 天</td><td>DNS-01 / HTTP-01</td><td>必须先建 <strong>EAB 凭据</strong>（7 天失效）</td></tr><tr><td>ZeroSSL</td><td>ACME CA</td><td>90 天</td><td>DNS-01 / HTTP-01</td><td>首次使用自动换取 EAB</td></tr><tr><td>FreeSSL / LiteSSL</td><td>ACME CA</td><td>90 天</td><td>DNS-01 / HTTP-01</td><td>亚洲诚信出品，<strong>必须带 EAB</strong>，EAB 只能用一次</td></tr><tr><td>Buypass</td><td>ACME CA</td><td>180 天</td><td>DNS-01 / HTTP-01</td><td>挪威 CA，免费 180 天</td></tr><tr><td>自定义 ACME</td><td>ACME CA</td><td>以 CA 为准</td><td>取决于 CA</td><td>填目录地址即可对接私有 CA</td></tr><tr><td>阿里云免费证书</td><td>云厂商</td><td>3 个月</td><td>DNS 验证</td><td>单域名 DV，受账号免费额度限制</td></tr><tr><td>腾讯云免费证书</td><td>云厂商</td><td>3 个月</td><td>DNS 验证</td><td>单域名 DV，受账号免费额度限制</td></tr><tr><td>火山引擎免费证书</td><td>云厂商</td><td>以控制台为准</td><td>DNS 验证</td><td><code>QuickApplyCertificate</code>，单域名 DV</td></tr><tr><td>TrustAsia 亚洲诚信</td><td>商业 CA</td><td>按产品</td><td>DNS / CNAME / 文件</td><td>支持 DV / OV / EV</td></tr><tr><td>自签证书</td><td>本地</td><td>默认 365 天</td><td>无需验证</td><td>测试 / 内网用</td></tr><tr><td>上传自有证书</td><td>导入</td><td>以证书为准</td><td>无需验证</td><td>只入库，之后同样可部署与监控</td></tr></tbody></table><h2 id="申请任务的字段" tabindex="-1">申请任务的字段 <a class="header-anchor" href="#申请任务的字段" aria-label="Permalink to &quot;申请任务的字段&quot;">​</a></h2><p>在阶段里添加 <strong>证书申请（CertApply）</strong> 任务，核心字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>证书域名</td><td>可填多个；泛域名写 <code>*.example.com</code>，<strong>同时要加 <code>example.com</code></strong> 才能覆盖主域</td></tr><tr><td>证书颁发机构</td><td>上面 12 种来源之一</td></tr><tr><td>联系邮箱</td><td>CA 用来发到期提醒，建议填真实邮箱</td></tr><tr><td>EAB 凭据</td><td>仅 Google / FreeSSL-LiteSSL / 自定义 CA 出现，从授权管理里选</td></tr><tr><td>域名验证方式</td><td>DNS 验证（推荐，支持泛域名）/ HTTP 验证</td></tr><tr><td>DNS 授权</td><td>DNS 验证时选，必须是支持 DNS 能力的云厂商授权</td></tr><tr><td>密钥类型</td><td>ECC 256（推荐）/ ECC 384 / RSA 2048 / 3072 / 4096</td></tr><tr><td>提前续期天数</td><td>默认 20 天，没到时间自动跳过签发</td></tr><tr><td>首选证书链</td><td>默认用 CA 默认链；老设备兼容选 <code>ISRG Root X1</code> / <code>GlobalSign</code></td></tr><tr><td>证书配置档</td><td>CA 默认 / <code>tlsserver</code> / <code>shortlived</code> / <code>classic</code></td></tr><tr><td>强制续期</td><td>忽略剩余天数，立刻重新签</td></tr><tr><td>证书已存在且未过期就跳过</td><td>默认开启，避免重复申请触发限流</td></tr></tbody></table><p>高级设置里还有 DNS 传播等待、传播校验重试次数、申请失败重试次数、跳过本地 DNS 校验等参数，遇到「DNS 没生效就通知 CA」时优先调这几个。</p><h2 id="dns-01-还是-http-01" tabindex="-1">DNS-01 还是 HTTP-01？ <a class="header-anchor" href="#dns-01-还是-http-01" aria-label="Permalink to &quot;DNS-01 还是 HTTP-01？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>要求</th></tr></thead><tbody><tr><td><strong>DNS-01</strong></td><td>泛域名、站点不对外暴露、内网服务</td><td>域名 DNS 托管在已支持的服务商（阿里云 / 腾讯云 / 华为云 / Cloudflare / GoDaddy / NameSilo）</td></tr><tr><td><strong>HTTP-01</strong></td><td>单域名、站点 80 端口可从公网访问</td><td>能把验证文件对外提供；可写入本机目录或上传到远程主机</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">泛域名必须用 DNS-01</p><p>HTTP-01 无法验证 <code>*.example.com</code>。如果解析商不在支持列表里，做法是把域名的 NS 指到支持的服务商（阿里云 / 腾讯云 / Cloudflare 等），再走 DNS 验证。</p></div><h2 id="acme-签发流程" tabindex="-1">ACME 签发流程 <a class="header-anchor" href="#acme-签发流程" aria-label="Permalink to &quot;ACME 签发流程&quot;">​</a></h2><ol><li>读取 / 创建 ACME 账户（密钥按「用户 + CA」隔离保存，加密存储）。</li><li>创建订单 → 逐个域名完成 DNS-01 / HTTP-01 挑战。</li><li>轮询授权状态 → 生成密钥与 CSR → finalize → 下载证书链。</li><li>保存证书（私钥 AES-GCM 加密入库）+ 写入 <code>data/certs/{userId}/</code>。</li><li>输出变量 <code>cert.crt</code> / <code>cert.key</code> / <code>cert.domain</code> / <code>cert.expiresTime</code> 供部署任务使用。</li></ol><div class="tip custom-block"><p class="custom-block-title">国内网络访问 Google / ZeroSSL 超时</p><p>系统设置 → <strong>网络设置</strong> 里可以配 HTTP 代理（<code>http://</code>、<code>https://</code>、<code>socks5://</code>），也可以给 CA 域名配<strong>反向代理域名</strong>。任务里还能单独勾「使用代理访问 CA」或填自定义反代地址。日志会写明实际走了哪条路。</p></div><h2 id="关于-eab" tabindex="-1">关于 EAB <a class="header-anchor" href="#关于-eab" aria-label="Permalink to &quot;关于 EAB&quot;">​</a></h2><p>Google 的 EAB key 创建后 <strong>7 天失效</strong>；FreeSSL / LiteSSL 的 EAB <strong>注册成功一次就作废</strong>。所以：</p><ul><li>EAB 统一放在 <strong>授权管理 → 证书签发</strong>，任务里只选不填。</li><li>首次注册成功后，账户私钥与账户 URL 会同时写回<strong>任务</strong>和<strong>EAB 授权</strong>，其它流水线复用同一份 EAB 时不会重复注册。</li><li>CA 侧的账户被删 / 换了 CA 时，系统会改用 EAB 重新注册一次。</li><li>报错 <code>External account binding has already been used</code> → 这条 EAB 已经用过了，去轮换一份新的。</li></ul><p>FreeSSL 的 ACME 目录地址是 <code>https://acme.litessl.com/acme/v2/directory</code>（老的 <code>acme.freessl.cn</code> 已下线）。该目录 <code>externalAccountRequired = true</code>，<strong>必须带 EAB</strong>。域名有严格 CAA 记录时，要把 <code>trustasia.com</code> 加进去。</p><h2 id="云厂商免费证书" tabindex="-1">云厂商免费证书 <a class="header-anchor" href="#云厂商免费证书" aria-label="Permalink to &quot;云厂商免费证书&quot;">​</a></h2><p>阿里云、腾讯云、火山引擎的流程一致：申请 → 取回验证记录并自动写入 DNS → 轮询 → 入库。</p><ul><li><strong>阿里云</strong>：<code>CreateCertificateForPackageRequest</code>（<code>ProductCode=digicert-free-1-free</code>，即 3 个月个人测试证书）→ <code>DescribeCertificateState</code>。</li><li><strong>腾讯云</strong>：<code>ApplyCertificate</code>（<code>PackageType=83</code>）→ <code>DescribeCertificate</code> → <code>DownloadCertificate</code>。</li><li><strong>火山引擎</strong>：<code>QuickApplyCertificate</code> → <code>CertificateGetInstance</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">免费额度是有限的</p><p>免费证书依赖账号的免费额度，额度用尽会直接返回业务错误；而且都是<strong>单域名 DV</strong>，泛域名请走 ACME。</p></div><h2 id="自签与导入" tabindex="-1">自签与导入 <a class="header-anchor" href="#自签与导入" aria-label="Permalink to &quot;自签与导入&quot;">​</a></h2><ul><li><strong>自签</strong>：不需要域名验证，适合内网、测试环境；默认有效期 365 天。</li><li><strong>导入</strong>：<code>POST /api/cert/import</code> 接收 PEM（证书链 + 私钥），入库前会校验 PEM 头是否齐全、证书与私钥是否成对。导入的证书与流水线签发的证书<strong>完全等价</strong> —— 部署与到期提醒读的都是证书库。</li></ul><h2 id="证书库与导出" tabindex="-1">证书库与导出 <a class="header-anchor" href="#证书库与导出" aria-label="Permalink to &quot;证书库与导出&quot;">​</a></h2><p><img src="'+a+'" alt="证书详情"></p><p>证书库显示域名、签发机构、生效 / 到期时间、剩余天数，点「查看」可以分标签看证书、证书链与私钥。</p><p>导出格式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/cert/{id}/download?format=pem|der|pfx|p7b|jks|nginx&amp;type=cert|key&amp;password=xxx</span></span></code></pre></div><ul><li><strong>JKS</strong> 是 Sun 私有格式，无纯 Python 写入实现：服务端先生成 PKCS#12，再调用 JDK <code>keytool</code> 转换。没装 JDK 时会提示改用 PFX（Java 同样能加载 PKCS#12）。</li><li><strong>PFX 兼容性</strong>：Windows Server 2016 / 2008 老系统可在申请任务的「PFX 兼容性」里选 SHA1 + 3DES 的组合。</li></ul><h2 id="常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#常见报错" aria-label="Permalink to &quot;常见报错&quot;">​</a></h2><table tabindex="0"><thead><tr><th>报错</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>Did not find challenge value</code> / <code>incorrectResponse</code></td><td>DNS 记录还没生效就通知了 CA</td><td>把「DNS 传播等待」调到 300~600 秒，或加大传播校验重试次数</td></tr><tr><td><code>Unknown external account binding (EAB) key</code></td><td>Google EAB 过期（7 天）</td><td>更新 EAB 授权后重跑</td></tr><tr><td><code>External account binding has already been used</code></td><td>一次性 EAB 被复用</td><td>轮换 EAB</td></tr><tr><td><code>The bound account does not exist</code></td><td>EAB 与 CA 对不上</td><td>重新取一份 EAB，确认「所属 CA」选对</td></tr><tr><td>域名验证失败但 DNS 记录看着是对的</td><td>权威 NS 不是你以为的那家</td><td><code>dig NS example.com</code> 确认解析商，再换对应授权</td></tr></tbody></table><p>更多见 <a href="./troubleshoot.html">故障排查</a>。</p>',33)])])}const g=d(c,[["render",s]]);export{u as __pageData,g as default};
